            stx: &mut StateTransaction<'_, '_>,
            account: &AccountId,
        ) {
            let permission: Permission =
                iroha_executor_data_model::permission::peer::CanManageLaneRelayEmergency.into();
            stx.world
                .account_permissions
                .insert(account.clone(), BTreeSet::from([permission]));
